mapper.update:
UPDATE booking_request SET
    status = '1',
    update_by = #{updateBy},
    update_date = #{updateDate}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND del_flag = '0'
    AND status = '0'

UPDATE booking_request SET
    registration_id = #{registrationId},
    update_by = #{updateBy},
    update_date = #{updateDate}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND del_flag = '0'
    AND status = '1'

UPDATE booking_request SET
    status = '2',
    reject_reason = #{rejectReason},
    update_by = #{updateBy},
    update_date = #{updateDate}
WHERE id = #{id}
    AND company_id = #{companyId}
    AND del_flag = '0'
    AND status = '0'

